"Зимние праздники: Морозко и Снегурка выходят к людям, духи Ветра и Воды встречаются чаще, в источниках — подарки.":"Winter holidays: Morozko and Snegurka come out to people, Wind and Water spirits appear more often, and wellsprings hold gifts.",
"Масленица":"Maslenitsa",
"Провожаем зиму! Духи Огня встречаются вдвое чаще, в источниках много мёда («блинов»), опыт ×1,5.":"Farewell to winter! Fire spirits appear twice as often, wellsprings are full of honey (“pancakes”), XP ×1.5.",
"Купальская ночь":"Kupala Night",
"Цветёт папоротник: Купалинка повсюду, духи Огня, Воды и Леса чаще, ночью сияющие — вдвое чаще.":"The fern is blooming: Kupalinka is everywhere, Fire, Water and Forest spirits appear more often, and at night shiny ones — twice as often.",
"Покров":"Pokrov",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в источниках больше добычи.":"First mists and frost: Wind and Water spirits appear more often, Listopadnitsa is everywhere, and wellsprings give more loot.",
"Велесова ночь":"Veles Night",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"The border between worlds is at its thinnest: Shadow spirits three times as often, Koschei awaits in great rifts, shiny Shadow spirits twice as often.",
"Этот источник теперь принадлежит Нави!":"This wellspring belongs to Nav now!",
"Твои духи будут служить Кощею!":"Your spirits will serve Koschei!",
"Орден Оберега? Никогда о таком не слышал.":"The Order of the Charm? Never heard of it.",
"Граница рухнет, и мы заберём весь город!":"The border will fall, and we'll take the whole city!",
"Думаешь, оберегом меня остановишь?":"You think a charm can stop me?",
"Тьма уже здесь, Ловчий. Смирись.":"The darkness is already here, Catcher. Accept it.",
