"Награда за сегодня уже получена — сейчас это тренировка (+100 опыта за победу).":"Today's reward is already claimed — this is practice now (+100 XP per win).",
"Награда за первую победу за день: 800 опыта, ✦ 500, обереги и мёд, +1 ★ дружбы.":"Reward for the first win of the day: 800 XP, ✦ 500, charms and honey, +1 ★ friendship.",
