"Победа не засчитана":"Win not counted",
"Сервер не подтвердил этот бой. Проверь интернет и попробуй снова.":"The server didn't confirm this battle. Check your connection and try again.",
"Защитники «{0}» отступили — Святилище «{1}» свободно!":"“{0}” defenders retreated — Shrine “{1}” is free!",
"Победа засчитана, но пока шёл бой, в Святилище сменились защитники.":"Win counted, but the defenders at the Shrine changed during the battle.",
"«Достойно, Ловчий», — {0} склоняет голову. Святилище «{1}» освящено тобой до конца дня.":"“Well fought, Catcher,” — {0} bows their head. Shrine “{1}” is consecrated by you until the end of the day.",
"Победа!":"Victory!",
"Поставь своего защитника — и Святилище перейдёт твоему клану.":"Place your defender — and the Shrine will pass to your clan.",
"Поражение":"Defeat",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"“Come back when you're stronger,” says {0}. Try a different team: check the guardian's elements and save your shields for its moves.",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"Good practice! Today's reward for a duel with {0} is already claimed.",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0} shakes your hand: “Fair fight!” Your friendship grows stronger.",
"<b>+1 ★</b> дружбы":"<b>+1 ★</b> friendship",
"Духи {0} оказались сильнее. Подбери команду против их стихий и попробуй снова — поединки с другом не ограничены.":"{0}'s spirits were stronger. Pick a team against their elements and try again — duels with a friend are unlimited.",
"Источник освобождён!":"Wellspring freed!",
"Прислужник растворился в тумане. Один из его духов — омрачённый {0} — остался рядом. Его ещё можно спасти!":"The minion dissolved into the mist. One of its spirits — a corrupted {0} — stayed behind. It can still be saved!",
"Спасти духа":"Save the spirit",
"Навь сильнее… пока":"Nav is stronger… for now",
"«{0}» — смеётся прислужник. Возьми духов, сильных против стихии «{1}», и возвращайся.":"“{0}” — the minion laughs. Bring spirits strong against the “{1}” element and come back.",
"Сдаться?":"Give up?",
