"Не JPEG":"Not a JPEG",
"Ты и {0} теперь друзья! Стартовый подарок уже в сумке.":"You and {0} are now friends! A starter gift is already in your bag.",
"Лови духов вместе со мной в «Духолове»! Открой ссылку — мы сразу станем друзьями, а тебе достанется стартовый подарок:\n{0}":"Catch spirits with me in Dukholov! Open the link — we'll become friends right away, and you'll get a starter gift:\n{0}",
