"Вход через {0} перейдёт к твоему текущему Ловчему, а у {1} его больше не будет.":"Sign-in with {0} will move to your current Catcher, and {1} will no longer have it.",
"У того Ловчего есть и другие способы входа — его прогресс останется доступен через них.":"That Catcher has other sign-in methods — their progress stays reachable through them.",
"<b>У того Ловчего не останется других способов входа — его прогресс станет недоступен навсегда.</b>":"<b>That Catcher will have no other way to sign in — their progress will be lost forever.</b>",
