"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"Each day XP comes in full up to {0}, then at half up to {1}, and beyond that at a quarter. The tutorial and Order signs always give full XP. Each day without play builds up rest XP ({2}, for at most {3} {4}): while you have it, XP is doubled.",
