"Опыт дают поимки, источники, разломы, святилища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"XP comes from catches, wellsprings, rifts, Shrines and quests. Your spirits grow with your level: you can power them up to the Catcher's level +5.",
"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"From level {0} spirits can be awakened: each star raises the spirit's level cap by {1} more, up to {2}.",
"Ищу настоящие места вокруг — Источники и Святилища появятся через несколько секунд":"Looking for real places around you — Wellsprings and Shrines will appear in a few seconds",
