"Источники и Святилища стоят у настоящих мест. Знаешь интересный объект рядом? Предложи его!":"Wellsprings and Shrines stand at real places. Know an interesting spot nearby? Suggest it!",
"<b>Подходят:</b> памятники, скульптуры, фонтаны, мозаики, необычные здания, храмы, парки, источники, смотровые площадки.":"<b>Good fits:</b> monuments, sculptures, fountains, mosaics, unusual buildings, temples, parks, springs, viewpoints.",
"<b>Не подходят:</b> частные дома и дворы, школы и детские сады, опасные места (проезжая часть, стройки), обычные магазины.":"<b>Not suitable:</b> private homes and yards, schools and kindergartens, dangerous places (roadways, construction sites), ordinary stores.",
"Стой рядом с объектом: снимок получает геометку, модератор сверяет её с точкой на карте.":"Stand next to the object: the photo gets a geotag, and the moderator checks it against the point on the map.",
