"До Разлома {0}. Подойди ближе — нужно {1} м.":"The Rift is {0} away. Get closer — you need to be within {1} m.",
"До Разлома {0}. Дальний пропуск: один Орден дарит каждый день, ещё — в Лавке. Позвать друзей можно, только подойдя к Святилищу.":"The Rift is {0} away. Remote Pass: the Order gives one every day, more in the Shop. You can invite friends only when you're at the Shrine.",
